import 'dart:convert';
import 'dart:io';

import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:weft_document/weft_document.dart';
import 'package:weft_engine/weft_engine.dart';

/// Browser golden geometry baseline for the `table_basic` conformance case.
///
/// The reference is generated by `tool/browser_references.mjs` and committed
/// under `conformance/reference/`. Column widths follow the engine's
/// proportional auto layout, so cell geometry compares with a small
/// algorithmic tolerance while structural relations (row heights, span
/// coverage, adjacency) compare exactly.
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  final root = _workspaceRoot();
  final reference = jsonDecode(
    File(
      '${root.path}/conformance/reference/table_basic.geometry.json',
    ).readAsStringSync(),
  ) as Map<String, dynamic>;

  setUpAll(() => _loadFonts(root));

  test('table block geometry matches the Chrome reference', () {
    final source = File(
      '${root.path}/conformance/cases/table_basic.html',
    ).readAsStringSync();
    final document = const WeftNormalizer().normalize(
      source,
      id: 'table-basic-geometry',
    );
    expect(document.supportReport.canRender, isTrue);
    final layout = const WeftLayoutEngine().layout(document, width: 360);
    addTearDown(layout.dispose);

    final elements = (reference['elements'] as Map<String, dynamic>)
        .cast<String, Map<String, dynamic>>();
    // The sanitizer strips data-geo markers, so elements are mapped by
    // structural position in document order.
    const cellOrder = [
      'h1',
      'h2',
      'h3',
      'r1',
      'u1',
      'v1',
      'r2',
      'v2',
      'r3',
      'u3',
      'v3',
      'r4',
      'v4',
      's1',
      's2',
    ];
    final boxesByGeo = <String, Rect>{};
    var cellIndex = 0;
    var tableIndex = 0;
    var paragraphIndex = 0;
    void visit(WeftNode node) {
      if (node is! WeftElement) return;
      switch (node.tag) {
        case 'h2':
          boxesByGeo['title'] = _box(layout, node);
        case 'table':
          boxesByGeo['t${++tableIndex}'] = _box(layout, node);
        case 'caption':
          boxesByGeo['cap'] = _box(layout, node);
        case 'td' || 'th':
          boxesByGeo[cellOrder[cellIndex++]] = _box(layout, node);
        case 'p':
          boxesByGeo[paragraphIndex++ == 0 ? 'after' : 'tail'] = _box(
            layout,
            node,
          );
      }
      for (final child in node.children) {
        visit(child);
      }
    }

    visit(document.body!);

    for (final key in ['title', 'after', 'tail']) {
      expectRectClose(boxesByGeo[key]!, _elementRect(elements, key), 0.5,
          label: key);
    }
    // The caption and table boxes inherit the ~1px text-intrinsic rounding
    // of shrink-to-fit column measurement.
    for (final key in ['cap', 't1', 't2']) {
      expectRectClose(boxesByGeo[key]!, _elementRect(elements, key), 1.5,
          label: key);
    }
    for (final key in [
      'h1',
      'h2',
      'h3',
      'r1',
      'u1',
      'v1',
      'r2',
      'v2',
      'r3',
      'u3',
      'v3',
      'r4',
      'v4',
      's1',
      's2',
    ]) {
      expectRectClose(boxesByGeo[key]!, _elementRect(elements, key), 1.5,
          label: key);
    }

    expect(
      layout.size.height,
      moreOrLessEquals((reference['documentHeight'] as num).toDouble(),
          epsilon: 2),
      reason: 'Document height diverged from Chrome.',
    );
  });

  test('table structure obeys spans, rows and adjacency', () {
    final source = File(
      '${root.path}/conformance/cases/table_basic.html',
    ).readAsStringSync();
    final document = const WeftNormalizer().normalize(
      source,
      id: 'table-basic-structure',
    );
    final layout = const WeftLayoutEngine().layout(document, width: 360);
    addTearDown(layout.dispose);

    final boxes = <String, Rect>{};
    const cellOrder = [
      'h1',
      'h2',
      'h3',
      'r1',
      'u1',
      'v1',
      'r2',
      'v2',
      'r3',
      'u3',
      'v3',
      'r4',
      'v4',
      's1',
      's2',
    ];
    var cellIndex = 0;
    void visit(WeftNode node) {
      if (node is! WeftElement) return;
      if (node.tag == 'td' || node.tag == 'th') {
        boxes[cellOrder[cellIndex++]] = _box(layout, node);
      }
      for (final child in node.children) {
        visit(child);
      }
    }

    visit(document.body!);

    // Header row: three cells meet exactly at the shared edge centerlines.
    expect(boxes['h1']!.top, boxes['h2']!.top);
    expect(boxes['h2']!.left, moreOrLessEquals(boxes['h1']!.right, epsilon: 1));
    expect(boxes['h3']!.left, moreOrLessEquals(boxes['h2']!.right, epsilon: 1));
    expect(boxes['h1']!.height, boxes['h2']!.height);
    expect(boxes['h1']!.height, boxes['h3']!.height);

    // Data rows advance by one row height.
    final rowStep = boxes['r1']!.top - boxes['h1']!.top;
    expect(rowStep, greaterThan(0));
    expect(boxes['r2']!.top - boxes['r1']!.top, moreOrLessEquals(rowStep));
    expect(boxes['r3']!.top - boxes['r2']!.top, moreOrLessEquals(rowStep));
    expect(boxes['r4']!.top - boxes['r3']!.top, moreOrLessEquals(rowStep));

    // colspan: the merged cell covers both leading columns and ends at the
    // shared centerline with v2.
    expect(boxes['r2']!.left, boxes['r1']!.left);
    expect(
      boxes['r2']!.right,
      moreOrLessEquals(boxes['v2']!.left, epsilon: 1),
    );

    // rowspan: u3 spans two rows exactly.
    expect(
      boxes['u3']!.height,
      moreOrLessEquals(boxes['r3']!.height * 2, epsilon: 1),
    );
    expect(
        boxes['u3']!.bottom, moreOrLessEquals(boxes['r4']!.bottom, epsilon: 1));

    // Separate model: gutters of 4px between the cells of the second table.
    expect(boxes['s2']!.left - boxes['s1']!.right,
        moreOrLessEquals(4, epsilon: 1));
  });
}

Rect _box(WeftLayoutResult layout, WeftElement element) {
  return layout.boxes.singleWhere((box) => box.nodeId == element.id).rect;
}

Rect _elementRect(Map<String, Map<String, dynamic>> elements, String key) {
  final element = elements[key];
  expect(element, isNotNull, reason: 'Reference is missing "$key".');
  return Rect.fromLTWH(
    (element!['left'] as num).toDouble(),
    (element['top'] as num).toDouble(),
    (element['width'] as num).toDouble(),
    (element['height'] as num).toDouble(),
  );
}

void expectRectClose(Rect actual, Rect expected, double epsilon,
    {required String label}) {
  expect(
    actual.left,
    moreOrLessEquals(expected.left, epsilon: epsilon),
    reason: '$label left diverged from Chrome.',
  );
  expect(
    actual.top,
    moreOrLessEquals(expected.top, epsilon: epsilon),
    reason: '$label top diverged from Chrome.',
  );
  expect(
    actual.width,
    moreOrLessEquals(expected.width, epsilon: epsilon),
    reason: '$label width diverged from Chrome.',
  );
  expect(
    actual.height,
    moreOrLessEquals(expected.height, epsilon: epsilon),
    reason: '$label height diverged from Chrome.',
  );
}

Future<void> _loadFonts(Directory root) async {
  final fontDir = '${root.path}/conformance/fonts';
  final roboto = FontLoader('WeftRoboto');
  for (final file in const [
    'Roboto-Regular.ttf',
    'Roboto-Bold.ttf',
    'Roboto-Italic.ttf',
    'Roboto-BoldItalic.ttf',
  ]) {
    final bytes = await File('$fontDir/$file').readAsBytes();
    roboto.addFont(Future.value(ByteData.sublistView(bytes)));
  }
  await roboto.load();

  final mono = FontLoader('WeftRobotoMono');
  for (final file in const [
    'RobotoMono-Regular.ttf',
    'RobotoMono-Bold.ttf',
  ]) {
    final bytes = await File('$fontDir/$file').readAsBytes();
    mono.addFont(Future.value(ByteData.sublistView(bytes)));
  }
  await mono.load();
}

Directory _workspaceRoot() {
  var current = Directory.current.absolute;
  while (true) {
    final pubspec = File('${current.path}/pubspec.yaml');
    if (pubspec.existsSync() &&
        pubspec.readAsStringSync().contains(
              RegExp(r'^workspace:', multiLine: true),
            )) {
      return current;
    }
    final parent = current.parent;
    if (parent.path == current.path) {
      throw StateError('Could not find the Weft workspace root.');
    }
    current = parent;
  }
}
